package main

import (
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/gin-gonic/gin"
)

var auditLogger *log.Logger

func init() {
	logFile, err := os.OpenFile("/var/log/app/audit.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		log.Fatal(err)
	}
	auditLogger = log.New(logFile, "", log.LstdFlags)
}

// sanitizeForDisplay removes HTML tags but does NOT sanitize log-injection chars
func sanitizeForDisplay(input string) string {
	input = strings.ReplaceAll(input, "<", "&lt;")
	input = strings.ReplaceAll(input, ">", "&gt;")
	return input
}

func handleLogin(c *gin.Context) {
	username := c.PostForm("username")
	password := c.PostForm("password")

	// Sanitize for response display
	safeUsername := sanitizeForDisplay(username)

	// Log the authentication attempt - username is written directly to log
	// This allows newline injection and log forging
	auditLogger.Printf("AUTH_ATTEMPT: user=%s src_ip=%s user_agent=%s",
		username, c.ClientIP(), c.Request.UserAgent())

	if authenticateUser(username, password) {
		auditLogger.Printf("AUTH_SUCCESS: user=%s src_ip=%s", username, c.ClientIP())
		c.JSON(200, gin.H{"status": "authenticated", "user": safeUsername})
	} else {
		auditLogger.Printf("AUTH_FAILURE: user=%s src_ip=%s", username, c.ClientIP())
		c.JSON(401, gin.H{"error": "invalid credentials", "attempted_user": safeUsername})
	}
}

func handleSearch(c *gin.Context) {
	query := c.Query("q")
	userID := c.GetHeader("X-User-ID")

	// Log search query - also vulnerable to injection via query param and header
	auditLogger.Printf("SEARCH: user_id=%s query=%s src_ip=%s",
		userID, query, c.ClientIP())

	results := performSearch(query)
	c.JSON(200, gin.H{"results": results, "query": sanitizeForDisplay(query)})
}

func handleAdminAction(c *gin.Context) {
	action := c.PostForm("action")
	target := c.PostForm("target")
	adminUser := c.GetHeader("X-Admin-User")

	// Critical admin audit log - injectable via all three parameters
	auditLogger.Printf("ADMIN_ACTION: admin=%s action=%s target=%s src_ip=%s",
		adminUser, action, target, c.ClientIP())

	c.JSON(200, gin.H{"status": "executed", "action": sanitizeForDisplay(action)})
}

func authenticateUser(username, password string) bool {
	// Simplified auth check
	return username == "admin" && password == "secret123"
}

func performSearch(query string) []string {
	return []string{fmt.Sprintf("result for: %s", sanitizeForDisplay(query))}
}

func main() {
	r := gin.Default()

	r.POST("/login", handleLogin)
	r.GET("/search", handleSearch)
	r.POST("/admin/action", handleAdminAction)

	// Listen on all interfaces - service exposure controlled by network layer
	r.Run(":8080")
}
